from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse

app = FastAPI()

STORE: dict[int, str] = {}
STORE[{{item_id}}] = "in the tower"

# >>> EDIT START
# Methods
READ = "GET"
SEND = "GET"
CANCEL = "GET"
# Status codes
FOUND = 500
CREATED = 500
MISSING = 500
BAD_DATA = 500
NOT_LOGGED_IN = 500
NOT_ALLOWED = 500
# <<< EDIT END


def signal(code: int, **body: object) -> JSONResponse:
    return JSONResponse(status_code=code, content=body)


def pilot(request: Request) -> str | None:
    return request.headers.get("x-pilot")


async def read(item_id: int, request: Request) -> Response:
    if not pilot(request):
        return signal(NOT_LOGGED_IN, error="who are you?")
    if item_id not in STORE:
        return signal(MISSING, error="no such {{thing}}")
    return signal(FOUND, id=item_id, status=STORE[item_id])


async def send(request: Request) -> Response:
    if not pilot(request):
        return signal(NOT_LOGGED_IN, error="who are you?")
    body = await request.json() if await request.body() else {}
    to = body.get("to") if isinstance(body, dict) else None
    if not isinstance(to, str) or not to:
        return signal(BAD_DATA, error="`to` is required")
    return signal(CREATED, id=99, to=to)


async def cancel(item_id: int, request: Request) -> Response:
    if not pilot(request):
        return signal(NOT_LOGGED_IN, error="who are you?")
    if request.headers.get("x-rank") != "{{rank}}":
        return signal(NOT_ALLOWED, error="only a {{rank}} can cancel")
    if item_id not in STORE:
        return signal(MISSING, error="no such {{thing}}")
    return Response(status_code=204)


app.add_api_route("/{{thing}}s/{item_id}", read, methods=[READ])
app.add_api_route("/{{thing}}s", send, methods=[SEND])
app.add_api_route("/{{thing}}s/{item_id}", cancel, methods=[CANCEL])
